	err := db.Where("id = ? AND initiator_id = ?", itemID, userID).First(&item).Error
	if err != nil {
		c.JSON(http.StatusNotFound, gin.H{"error": "friend_request not found"})
		return
	}
	c.JSON(http.StatusOK, item)
}

